const shipment = $json;
const previous = $("SELECT FROM v_active_shipment_for_tracking").item.json;
const previousEta = previous.eta;
const previousEtd = previous.etd;
const previousAtd = previous.atd;
const previousAta = previous.ata;
const previousStatus = previous.shipment_status;

function splitMilestone(milestone) {
  if (!milestone?.date) return { estimated: null, actual: null };
  return milestone.actual
    ? { estimated: null, actual: milestone.date }
    : { estimated: milestone.predictiveEta || milestone.date, actual: null };
}

// Fecha calendario en zona de negocio (Mexico): estable entre corridas -> corta el loop DATE/TZ
function toBusinessDate(dateValue) {
  if (!dateValue) return null;
  const d = new Date(dateValue);
  if (isNaN(d.getTime())) return null;
  return d.toLocaleDateString('en-CA', { timeZone: 'America/Mexico_City' });
}

// Formatear fecha a timestamp con zona horaria compatible con PostgreSQL
function toPostgresTimestamp(dateValue) {
  if (!dateValue) return null;
  const d = new Date(dateValue);
  if (isNaN(d.getTime())) return null;

  const pad = (num, size = 2) => String(num).padStart(size, '0');

  const year = d.getUTCFullYear();
  const month = pad(d.getUTCMonth() + 1);
  const day = pad(d.getUTCDate());
  const hours = pad(d.getUTCHours());
  const minutes = pad(d.getUTCMinutes());
  const seconds = pad(d.getUTCSeconds());
  const ms = pad(d.getUTCMilliseconds(), 3);

  return `${year}-${month}-${day} ${hours}:${minutes}:${seconds}.${ms}000+00`;
}

const pol = shipment.route?.pol;
const { estimated: polEstimated, actual: atd } = splitMilestone(pol);
const etd = atd ? null : polEstimated;

const pod = shipment.route?.pod;
const { estimated: podEstimated, actual: ata } = splitMilestone(pod);
const eta = ata ? null : podEstimated;

const newEta = eta ?? previousEta;

const apiStatus = shipment.metadata?.shippingStatus ?? null;
const shipmentStatus = apiStatus !== null ? apiStatus : previousStatus;

let terminal = null;
for (const container of shipment.containers ?? []) {
  const discEvent = container.events?.find(e => e.eventCode === 'DISC');
  if (discEvent?.facility?.name) {
    terminal = discEvent.facility.name;
    break;
  }
}

function fieldChanged(prevValue, newValue) {
  return toBusinessDate(prevValue) !== toBusinessDate(newValue);
}

const changeCandidates = [
  { field: 'ata', changed: fieldChanged(previousAta, ata),    oldValue: previousAta, newValue: ata },
  { field: 'atd', changed: fieldChanged(previousAtd, atd),    oldValue: previousAtd, newValue: atd },
  { field: 'eta', changed: fieldChanged(previousEta, newEta), oldValue: previousEta, newValue: newEta },
  { field: 'etd', changed: fieldChanged(previousEtd, etd),    oldValue: previousEtd, newValue: etd },
];

const detectedChange = changeCandidates.find(c => c.changed);
const fieldName = detectedChange?.field ?? null;

const oldDateValue = toBusinessDate(detectedChange?.oldValue ?? null);
const newDateValue = toBusinessDate(detectedChange?.newValue ?? null);

//Fecha del metadata: 
const ultima_actualizacion = toPostgresTimestamp(shipment.metadata?.updatedAt);

//Actualización 16/07/26 añadido shipment_type
const shipment_type = (shipment.metadata?.shipmentType ?? null);

//shipmentNumber = tracking_key

const shipment_number = (shipment.metadata?.shipmentNumber ?? null);
const w = shipment.metadata?.warnings;
const warnings = Array.isArray(w) && w.length > 0 ? w : [];
return {
  json: {
    shipment_id: previous.shipment_id,
    tracking_key: shipment_number,
    shipment_type: shipment_type,
    eta: toBusinessDate(newEta),
    etd: toBusinessDate(etd),
    atd: toBusinessDate(atd),
    ata: toBusinessDate(ata),
    shipment_status: shipmentStatus,
    terminal: terminal,
    ultima_actualizacion: ultima_actualizacion,
    field_name: fieldName,
    old_date_value: oldDateValue,
    new_date_value: newDateValue,
    tracking_source: 'SAFECUBE_API',
    tracking_status: apiStatus,
    audit_execution_id: $('Set Request_ID').first().json.request_id,
    n8n_execution_id: $execution.id,
    warnings: warnings,
    raw_tracking_payload: shipment
  }
};

const requestId = ['TRK', Date.now(), Math.random().toString(36).substring(2, 8).toUpperCase()].join('-');

// NOTA: este flujo NO guarda estado por tracking_key. Relee la clave de
// v_active_shipments_for_tracking en cada corrida y actualiza por shipment_id, asi
// que si el portal corrige el MBL de un embarque, la clave vieja deja de
// consultarse sola y la nueva entra en el siguiente sondeo. No hace falta avisar a
// n8n de la clave anterior.
//
// El cuerpo del webhook se ignora a proposito: hoy el webhook es solo un "recorre
// todos ahora". Ver el refresco selectivo pendiente en
// docs/pendientes-coordinacion-compras-internacionales.md (punto 7).

return {
  json: {
    request_id: requestId
  }
};

const errorData = $json;
const errorMessage = errorData?.error?.message
  || errorData?.message
  || 'Error desconocido en UPDATE ETA And Dates';
const trackingKey = errorData?.tracking_key
  || errorData?.metadata?.shipmentNumber
  || 'SIN_TRACKING_KEY';

return {
  json: {
    error: {
      message: errorMessage,
      level: errorData?.error?.level || 'error',
      description: errorData?.error?.description || errorMessage
    },
    tracking_key: trackingKey,
    message: errorMessage,
    ...errorData
  }
};

const rawMessage = $input.item.json.error?.message ?? '';
let parsedMessage;
try {
  const jsonString = rawMessage.substring(rawMessage.indexOf('{'), rawMessage.lastIndexOf('}') + 1);
  parsedMessage = JSON.parse(jsonString.replace(/\\"/g, '"'));
} catch (e) {
  parsedMessage = { message: rawMessage, errorCode: 'PARSE_ERROR', details: String(e) };
}

const tracking_key = $input.item.json.tracking_key
  ?? $input.item.json.metadata?.shipmentNumber
  ?? $("SELECT FROM v_active_shipment_for_tracking").item.json.tracking_key ?? null;

const shipment_id = $("SELECT FROM v_active_shipment_for_tracking").item.json.shipment_id ?? null;

return { json: { shipment_id, tracking_key, parsedMessage } };
